def countRobotGroups(robots: list[list[int]]) -> int:
    # Each robot: [position, radius]. Interval: [pos - radius, pos + radius]
    if not robots:
        return 0

    intervals = [[pos - r, pos + r] for pos, r in robots]
    intervals.sort(key=lambda x: x[0])

    groups = 1
    current_end = intervals[0][1]

    for start, end in intervals[1:]:
        if start <= current_end:
            current_end = max(current_end, end)
        else:
            groups += 1
            current_end = end

    return groups

#include <vector>
#include <algorithm>

class Solution {
public:
    int countRobotGroups(std::vector<std::vector<int>>& robots) {
        if (robots.empty()) return 0;
        std::vector<std::pair<long long, long long>> intervals;
        for (auto const& r : robots) {
            intervals.push_back({(long long)r[0] - r[1], (long long)r[0] + r[1]});
        }
        std::sort(intervals.begin(), intervals.end());

        int groups = 1;
        long long current_end = intervals[0].second;

        for (size_t i = 1; i < intervals.size(); ++i) {
            if (intervals[i].first <= current_end) {
                current_end = std::max(current_end, intervals[i].second);
            } else {
                groups++;
                current_end = intervals[i].second;
            }
        }
        return groups;
    }
};

import java.util.*;

class Solution {
    public int countRobotGroups(int[][] robots) {
        if (robots.length == 0) return 0;
        long[][] intervals = new long[robots.length][2];
        for (int i = 0; i < robots.length; i++) {
            intervals[i][0] = (long) robots[i][0] - robots[i][1];
            intervals[i][1] = (long) robots[i][0] + robots[i][1];
        }
        Arrays.sort(intervals, (a, b) -> Long.compare(a[0], b[0]));

        int groups = 1;
        long currentEnd = intervals[0][1];

        for (int i = 1; i < intervals.length; i++) {
            if (intervals[i][0] <= currentEnd) {
                currentEnd = Math.max(currentEnd, intervals[i][1]);
            } else {
                groups++;
                currentEnd = intervals[i][1];
            }
        }
        return groups;
    }
}

function countRobotGroups(robots) {
    if (robots.length === 0) return 0;
    const intervals = robots.map(([pos, r]) => [pos - r, pos + r]);
    intervals.sort((a, b) => a[0] - b[0]);

    let groups = 1;
    let currentEnd = intervals[0][1];

    for (let i = 1; i < intervals.length; i++) {
        if (intervals[i][0] <= currentEnd) {
            currentEnd = Math.max(currentEnd, intervals[i][1]);
        } else {
            groups++;
            currentEnd = intervals[i][1];
        }
    }
    return groups;
}
